const $=s=>document.querySelector(s),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let pages=[],assetMap={},current,photos=[],photoIndex=0;const titles={'/':'Beranda','/pre-school':'Pre-School','/homeschooling-sd-smp-1':'Homeschooling SD','/about-6':'Homeschooling SMP–SMA','/kursus-3a-pelangi-indonesia':'Program Kursus','/form-coba-gratis':'Pendaftaran Coba Gratis','/faq':'Pertanyaan Umum','/dokumen-pendaftaran-siswa-baru':'Dokumen Pendaftaran'};const title=p=>titles[p.path]||p.title;const page=p=>pages.find(d=>d.path===p);const img=(p,n=0)=>page(p)?.images[n]?.src||page('/')?.images[0]?.src||'';const photo=(src,alt,cls='')=>`<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy">`;const btn=(text,url,light=false)=>`<a class="button ${light?'light':''}" href="${esc(url)}">${esc(text)}</a>`;function card(p,desc,tag){return `<a class="card" href="${esc(p.path)}">${p.images[0]?photo(p.images[0].src,title(p)):''}<div class="card-body"><span class="tag">${esc(tag||'PELANGI INDONESIA')}</span><h3>${esc(title(p))}</h3><p>${esc(desc||p.blocks.find(b=>b.tag==='p'&&b.text.length>70)?.text.slice(0,150)||'Kenali program dan kegiatan Pelangi Indonesia.')}</p><span class="arrow">Jelajahi selengkapnya ↗</span></div></a>`}function head(t,k='JELAJAHI PELANGI INDONESIA'){return `<section class="pagehead"><div class="breadcrumb"><a href="/">Beranda</a> / ${esc(t)}</div><p class="eyebrow" style="margin-top:35px">${k}</p><h1>${esc(t)}</h1></section>`}function aside(){return `<aside class="sidebox"><p class="eyebrow">MARI BERKENALAN</p><h3>Temukan program yang tepat untuk anak Anda.</h3><p>Diskusikan kebutuhan dan jadwalkan kunjungan bersama tim sekolah.</p>${btn('Daftar coba gratis ↗','/form-coba-gratis')}<a href="/kontak">Hubungi sekolah →</a><a href="/faq">Pertanyaan umum →</a></aside>`}function home(){const h=page('/');return `<section class="hero"><div class="hero-copy"><p class="eyebrow">SEKOLAH INKLUSI • YOGYAKARTA & BANTUL</p><h1>Ruang tumbuh<br>untuk <em>setiap<br>warna anak.</em></h1><p class="lead">Belajar, bermain, dan menjadi diri sendiri. Bersama Pelangi Indonesia, setiap anak mendapat ruang untuk mengembangkan potensi istimewanya.</p><div class="actions">${btn('Temukan program ↗','/sekolah')}${btn('Kenali sekolah kami','/tentang-kami',true)}</div><div class="hero-meta"><span>✦ Pendidikan inklusif</span><span>✦ Pendekatan personal</span><span>✦ Sejak 2003</span></div></div><div class="hero-photo">${photo(img('/'),'Anak-anak belajar dan bermain di Pelangi Indonesia').replace('loading="lazy"','loading="eager" fetchpriority="high"')}<div class="photo-note"><b>Smart and Balanced Kids</b>Belajar bersama. Bertumbuh dalam keberagaman.</div></div></section><div class="rainbow"></div><section class="wrap"><div class="section-head"><div><p class="eyebrow">LANGKAH KECIL, MASA DEPAN BESAR</p><h2>Temukan ruang belajar<br>yang sesuai.</h2></div><p>Dari masa awal tumbuh kembang hingga remaja, kami mendampingi perjalanan belajar setiap anak.</p></div><div class="cards">${card(page('/pre-school'),'Belajar melalui bermain untuk usia 3 bulan–7 tahun. Pilihan Half Day dan Full Day.','01 / PRA-SEKOLAH')}${card(page('/homeschooling-sd-smp-1'),'Pembelajaran yang menghargai kebutuhan, minat, dan potensi unik setiap anak.','02 / HOMESCHOOLING SD')}${card(page('/about-6'),'Ruang untuk mengeksplorasi minat dan mempersiapkan langkah selanjutnya.','03 / HOMESCHOOLING SMP–SMA')}</div></section><section class="tint"><div class="wrap split">${photo(img('/tentang-kami')||img('/',1),'Lingkungan belajar Pelangi Indonesia')}<div><p class="eyebrow">BERBEDA, BERSAMA, BERDAYA</p><h2>Setiap anak diterima.<br>Setiap potensi dirayakan.</h2><p class="lead">Sejak 2003, Pelangi Indonesia menghadirkan pendidikan dengan semangat inklusi, kemandirian, dan keberagaman budaya.</p><div class="values"><div><h3>Belajar aktif</h3><p>Anak mengeksplorasi, mencoba, dan menemukan melalui pengalaman.</p></div><div><h3>Pendekatan personal</h3><p>Pembelajaran yang memperhatikan kebutuhan unik anak.</p></div><div><h3>Multikultural</h3><p>Tumbuh dengan sikap saling menghargai dan menerima.</p></div><div><h3>Tumbuh seimbang</h3><p>Mendukung perkembangan akademik, sosial, dan emosional.</p></div></div>${btn('Tentang Pelangi Indonesia ↗','/tentang-kami')}</div></div></section><section class="wrap"><div class="section-head"><div><p class="eyebrow">LEBIH BANYAK CARA UNTUK BERTUMBUH</p><h2>Minat terasah.<br>Kesejahteraan terjaga.</h2></div></div><div class="cards" style="grid-template-columns:repeat(2,minmax(0,1fr))">${card(page('/kursus-3a-pelangi-indonesia'),'Baca tulis, matematika, sempoa, balet, taekwondo, tari, dan animasi.','KURSUS & PENGEMBANGAN MINAT')}${card(page('/s-projects-side-by-side'),'Asesmen, konseling, psikoterapi, dan dukungan tumbuh kembang.','RUMAH PSIKOLOGI')}</div></section><section class="quote"><div class="wrap"><p class="eyebrow">CERITA ORANG TUA</p><blockquote>“Pelangi Indonesia mengajarkan anak untuk lebih mandiri dan mampu menyelesaikan masalahnya sendiri, serta bertanggung-jawab ketika berbuat kesalahan.”</blockquote><p>Valentia <span style="opacity:.6">— Ibu dari Ezi, Kampus Colombo</span></p></div></section><section class="wrap"><div class="section-head"><div><p class="eyebrow">DARI KESEHARIAN KAMI</p><h2>Cerita penuh warna.</h2></div><a href="/blog">Semua cerita ↗</a></div><div class="cards">${pages.filter(p=>p.path.startsWith('/post/')).sort((a,b)=>a.path.includes('merayakan')?-1:b.path.includes('merayakan')?1:0).slice(0,3).map(p=>card(p,null,'CERITA & ARTIKEL')).join('')}</div></section><section class="tint"><div class="wrap"><p class="eyebrow">KENALI KAMI LEBIH DEKAT</p><h2>Sekilas kehidupan di Pelangi.</h2><div class="video-grid">${[['Y6UdM5wp_iE','Profile KB dan TK Pelangi Indonesia'],['g_VKK7RXges','Homeschooling Pelangi Indonesia'],['jrZtuzL9yYk','Tema Pembelajaran Minggu Ini (26–31 Oktober 2020)']].map(([id,t])=>`<div><iframe loading="lazy" src="https://www.youtube.com/embed/${id}" title="${t}" allowfullscreen></iframe><h3>${t}</h3></div>`).join('')}</div></div></section><section class="wrap split"><div><p class="eyebrow">AWALI PERJALANAN BERSAMA KAMI</p><h2>Mari temukan warna<br>istimewa anak Anda.</h2><p class="lead">Kenali kelas, bertemu edukator, dan rasakan suasana belajar melalui program coba gratis.</p></div><div class="actions">${btn('Daftar coba gratis ↗','/form-coba-gratis')}${btn('Hubungi sekolah','/kontak',true)}</div></section>`}
function blocks(p){return p.blocks.filter(b=>!['h1'].includes(b.tag)&&!['Memuat hari...','Pesan Sekarang','Minta Memesan'].includes(b.text)).map(b=>`<${b.tag==='h6'?'h3':b.tag}>${esc(b.text)}</${b.tag==='h6'?'h3':b.tag}>`).join('')}
function links(p){return `<div class="linklist">${p.links.filter(a=>a.text&&!a.url.startsWith('./')&&!a.url.startsWith('#')&&!['Beranda','Layanan','Daftar layanan'].includes(a.text)).map(a=>{let u=a.url;if(u.startsWith('/booking')||u.startsWith('/account'))u='https://www.pi-education.com'+u;return `<a href="${esc(u)}" ${u.startsWith('http')?'target="_blank" rel="noopener"':''}>${esc(a.text)} ↗</a>`}).join('')}</div>`}
function generic(p){return head(title(p))+`<div class="wrap content-layout"><article class="prose">${p.images[0]?photo(p.images[0].src,title(p)):''}${p.path.startsWith('/event-details/')?'<div class="note">Arsip acara dari website asli. Tanggal dan ketersediaan pendaftaran perlu dikonfirmasi kepada sekolah.</div>':''}${p.path.startsWith('/service-page/')?'<div class="note">Jadwal, biaya, dan ketersediaan kelas mengikuti konfirmasi tim sekolah.</div>':''}${blocks(p)}${links(p)}${p.images.length>1?`<div class="gallery">${p.images.slice(1).map((i,n)=>`<button data-photo="${n+1}">${photo(i.src,i.alt)}</button>`).join('')}</div>`:''}${p.path.startsWith('/service-page/')?btn('Tanyakan jadwal & pendaftaran ↗','https://wa.me/62811256238'):''}</article>${aside()}</div>`}
function faq(p){let entries=[],e;for(const b of p.blocks){if(b.text.includes('?')){e={q:b.text,a:[]};entries.push(e)}else if(e)e.a.push(b.text)}return head('Pertanyaan Umum')+`<div class="wrap content-layout"><div><p class="lead">Hal-hal yang sering ditanyakan orang tua tentang sekolah dan program kami.</p><div class="note">Beberapa keterangan bahasa pengantar berbeda antarhalaman sumber. Konfirmasikan informasi terbaru sesuai kelas kepada sekolah.</div><div class="faq">${entries.map(e=>`<details><summary>${esc(e.q)}</summary>${e.a.map(t=>`<p>${esc(t)}</p>`).join('')}</details>`).join('')}</div>${links(p)}</div>${aside()}</div>`}
let limit=12,filter='all';function listing(kind){const blog=kind==='blog',events=kind==='events';let items=pages.filter(p=>p.path.startsWith(blog?'/post/':events?'/event-details/':'/service-page/')&&!p.path.endsWith('/form'));if(!blog&&!events&&filter!=='all')items=items.filter(p=>p.title.toLowerCase().includes(filter));return head(blog?'Cerita & Artikel':events?'Arsip Acara':'Program Kursus')+`<div class="wrap"><p class="lead">${blog?'Kabar sekolah, inspirasi pengasuhan, dan cerita belajar bersama.':events?'Dokumentasi acara yang tercantum pada website asli. Hubungi sekolah untuk agenda dan ketersediaan terkini.':'Ruang untuk menemukan minat dan mengembangkan bakat. Pilih kelas yang ingin Anda kenali.'}</p>${!blog&&!events?`<div class="filters">${[['all','Semua kelas'],['jogja','Yogyakarta'],['bantul','Bantul'],['ballet','Balet']].map(([v,t])=>`<button data-filter="${v}" class="${v===filter?'active':''}">${t}</button>`).join('')}</div><div class="note">Jadwal dan harga mengikuti konfirmasi sekolah. Pemesanan kelas dilanjutkan melalui layanan resmi.</div>`:''}<div class="cards">${items.slice(0,limit).map(p=>card(p,null,blog?'ARTIKEL':events?'ARSIP ACARA':'KURSUS')).join('')}</div>${limit<items.length?`<button class="button loadmore" id="more">Tampilkan lebih banyak (${items.length-limit}) ↓</button>`:''}${!blog&&!events?`<section class="prose" style="margin-top:50px"><h2>Kursus Animasi</h2><p>Program Pendidikan Literasi Digital, Basic Animasi 3D, dan program profesional animasi 3D Blender.</p>${btn('Tanyakan program animasi ↗','/kontak')}</section>`:''}</div>`}
function contact(){return head('Mari berkenalan.','HUBUNGI KAMI')+`<div class="wrap contact-grid"><div><h2>Kami siap mendampingi<br>langkah pertama Anda.</h2><p>Hubungi kampus sesuai kebutuhan Anda, atau siapkan pesan melalui formulir di samping.</p>${[['Colombo','Jl. Colombo No. 8, Yogyakarta 55281','62811256238'],['Bantul','Jl. Mgr. Sugiyo Pranoto No. 14, Bantul 55711','62811256993']].map(([n,a,w])=>`<h3>Kampus ${n}</h3><p>${a}</p>${btn('WhatsApp '+n+' ↗','https://wa.me/'+w)}<p><a target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent('Pelangi Indonesia '+a)}">Lihat di Google Maps ↗</a></p>`).join('')}</div><form id="contact-form"><h3>Kirim pertanyaan</h3><p>Pesan disiapkan untuk WhatsApp. Anda meninjau dan mengirimkannya sendiri.</p><label for="name">Nama *</label><input id="name" name="nama" required autocomplete="name"><label for="email">Email *</label><input id="email" type="email" name="email" required autocomplete="email"><label for="phone">Nomor telepon *</label><input id="phone" type="tel" name="telepon" required autocomplete="tel"><label for="campus">Kampus tujuan</label><select id="campus" name="kampus"><option value="62811256238">Colombo</option><option value="62811256993">Bantul</option></select><label for="subject">Keterangan *</label><input id="subject" name="keterangan" required><label for="message">Pesan *</label><textarea id="message" name="pesan" required></textarea><button type="submit" class="button" style="margin-top:20px">Siapkan pesan WhatsApp ↗</button><p style="font-size:12px">Formulir ini tidak menyimpan data ke situs.</p></form></div>`}
function trial(){return head('Pendaftaran Coba Gratis')+`<div class="wrap content-layout"><article class="prose"><h2>Rasakan suasana belajar di Pelangi.</h2><p>Program coba gratis memberi kesempatan anak mengenal kelas, edukator, dan teman-teman sebelum bergabung.</p><div class="note">Formulir resmi berada di website sekolah. Pengisian dan pengiriman data anak dilakukan langsung di sana.</div><h3>Informasi yang perlu disiapkan</h3><p>Nama lengkap dan nama panggilan anak, nama orang tua/wali, email dan nomor telepon orang tua/wali, tanggal lahir anak, serta pilihan sekolah dan kelas.</p><p>Menurut website sumber, pendaftaran coba gratis berlaku maksimal satu bulan setelah pengisian formulir. Konfirmasikan jadwal yang tersedia kepada sekolah.</p>${btn('Buka formulir resmi sekolah ↗','https://www.pi-education.com/form-coba-gratis')}<div class="actions">${btn('Konsultasikan pilihan kelas','/kontak',true)}</div></article>${aside()}</div>`}
function gallery(p){photos=p.images;return head('Galeri Foto','KESEHARIAN PENUH WARNA')+`<div class="wrap"><p class="lead">Momen belajar, bermain, dan bertumbuh bersama Pelangi Indonesia.</p><div class="gallery">${photos.map((i,n)=>`<button data-photo="${n}">${photo(i.src,i.alt)}<span>${esc(i.alt==='Galeri kegiatan Sekolah Pelangi Indonesia'?'Kegiatan Pelangi Indonesia':i.alt)}</span></button>`).join('')}</div>${true?`<div class="note">Foto di atas berasal dari halaman program pada website asli. Delapan album khusus galeri menggunakan komponen dinamis Wix dan belum dapat disalin lengkap. ${btn('Lihat seluruh album di website asli ↗',p.source)}</div>`:''}<div class="linklist">${p.blocks.map(b=>`<span>${esc(b.text)}</span>`).join(' · ')}</div></div>`}
async function render(){let path=decodeURI(location.pathname).replace(/\/$/,'')||'/';current=page(path);photos=current?.images||[];document.title=(current?title(current):path==='/kontak'?'Hubungi Kami':path==='/acara'?'Arsip Acara':'Sekolah')+' | Sekolah Pelangi Indonesia';if(path==='/')$('#main').innerHTML=home();else if(path==='/kontak')$('#main').innerHTML=contact();else if(path==='/acara')$('#main').innerHTML=listing('events');else if(path==='/sekolah')$('#main').innerHTML=head('Sekolah untuk setiap warna anak.')+`<section class="wrap"><div class="cards">${['/pre-school','/homeschooling-sd-smp-1','/about-6'].map(p=>card(page(p))).join('')}</div></section>`;else if(path==='/form-coba-gratis')$('#main').innerHTML=trial();else if(path==='/faq')$('#main').innerHTML=faq(current);else if(path==='/gallery')$('#main').innerHTML=gallery(current);else if(path.startsWith('/blog'))$('#main').innerHTML=listing('blog');else if(path==='/kursus-3a-pelangi-indonesia')$('#main').innerHTML=listing('courses');else if(path==='/forum'||path==='/live-video')$('#main').innerHTML=head(current.title)+`<div class="wrap"><div class="note">Layanan ini menggunakan sistem Wix dan tersedia melalui website resmi sekolah.</div>${btn('Buka layanan resmi ↗',current.source)}</div>`;else if(current)$('#main').innerHTML=generic(current);else $('#main').innerHTML=head('Halaman belum ditemukan')+`<div class="wrap">${btn('Kembali ke beranda','/')}</div>`;$('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target),text=`Halo Pelangi Indonesia, saya ${d.get('nama')}.\nEmail: ${d.get('email')}\nTelepon: ${d.get('telepon')}\nKeterangan: ${d.get('keterangan')}\n${d.get('pesan')}`;window.open('https://wa.me/'+d.get('kampus')+'?text='+encodeURIComponent(text),'_blank','noopener')});$('#more')?.addEventListener('click',()=>{limit+=12;render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;limit=12;render()});document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{photoIndex=+b.dataset.photo;showPhoto();$('#lightbox').showModal()})}
function showPhoto(){const p=photos[photoIndex];$('#lightbox img').src=p.src;$('#lightbox img').alt=p.alt;$('#lightbox p').textContent=p.alt+' · '+(photoIndex+1)+' / '+photos.length}$('#prev').onclick=()=>{photoIndex=(photoIndex+photos.length-1)%photos.length;showPhoto()};$('#next').onclick=()=>{photoIndex=(photoIndex+1)%photos.length;showPhoto()};$('#menu').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};$('.search-toggle').onclick=()=>{$('#search').showModal();$('#query').focus()};document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));$('#query').oninput=e=>{let q=e.target.value.trim().toLowerCase();let found=q?pages.filter(p=>(title(p)+' '+p.blocks.map(b=>b.text).join(' ')).toLowerCase().includes(q)).slice(0,25):[];$('#results').innerHTML=found.map(p=>`<a href="${esc(p.path)}">${esc(title(p))}<small>${esc(p.path.startsWith('/post/')?'Artikel':p.path.startsWith('/service-page/')?'Kursus':'Halaman')}</small></a>`).join('')||(q?'<p>Tidak ada hasil. Coba kata lain atau hubungi sekolah.</p>':'')};document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;let u=new URL(a.href,location.href);if(u.origin===location.origin&&!u.hash&&!u.pathname.match(/\.(pdf|docx?|zip)$/)){e.preventDefault();history.pushState({},'',u.pathname);limit=12;filter='all';$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');document.querySelectorAll('nav details').forEach(d=>d.open=false);document.querySelectorAll('dialog').forEach(d=>d.close());render();scrollTo(0,0)}});window.onpopstate=()=>{render();scrollTo(0,0)};Promise.all([fetch('/data.json').then(r=>r.json()),fetch('/asset-map.json').then(r=>r.json())]).then(([p,m])=>{pages=p;assetMap=m;$('#logo').src=m['https://static.wixstatic.com/media/3e9cf0_7e839c5f902c461dafa47261b71765d5~mv2.jpg'];render()}).catch(()=>{$('#main').innerHTML='<div class="wrap"><h1>Halaman belum dapat dimuat.</h1><p>Silakan muat ulang halaman.</p></div>'});
